-- 공식 공고문(별첨 hwpx) 붙임6·8·9·10·11·12 서식을 원본 표 구조대로 재작성.
-- 공통: 맑은 고딕 임베드(render.ts), 지원업체 현황 표 + 본문 + 서명란.

-- 붙임6 사업참여 및 중복지원 금지 확약서
update public.document_templates set name='사업참여 및 중복지원 금지 확약서', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:12.5px;line-height:1.6}h1{text-align:center;font-size:18px;font-weight:800;letter-spacing:1px;margin:0 0 12px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:4px 0}th,td{border:1px solid #000;padding:6px 8px;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%}td{text-align:left;width:28%}.clause p{margin:5px 2px;text-align:justify}.stmt{margin:14px 2px 6px;text-align:justify}.sign{margin-top:16px;text-align:center;line-height:2.2}.foot{margin-top:8px;text-align:center;font-weight:800;font-size:14px}</style></head><body><h1>사업참여 및 중복지원 금지 확약서</h1><table><tr><th>업 체 명</th><td>{{business_name}}</td><th>대표자</th><td>{{owner_name}}</td></tr><tr><th>사업자등록번호</th><td>{{business_reg_no}}</td><th>전화번호</th><td>{{phone}}</td></tr><tr><th>업 태</th><td>{{business_type}}</td><th>종 목</th><td>{{item}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr></table><div class="clause"><p>1. 본인은 「대전 소상공인·자영업자 재기지원사업」 참여를 위하여 공고문 및 신청서 내용을 확인하였으며, 제반사항을 준수하여 사업을 수행하겠음.</p><p>2. 본인은 중앙정부 및 대전시·자치구 등 타 지원기관에서 실시하고 있는 경영개선 지원사업(경영환경개선사업)에 동일·유사한 내용으로 중복적인 지원을 받지 않겠음을 확약함.</p><p>3. 만약, 중복지원을 받는 경우 지원금 환수 조치 등 민·형사상의 책임을 부담할 것을 확인함.</p><p>4. 본인은 지원금 신청 내용과 증빙자료가 진실하며, 사실과 다르거나, 위법·부당한 방법을 통하여 지원받을 경우 지원액 전액 환수 및 향후 지원사업에서 배제되며, 발생하는 모든 법적 책임을 부담할 것을 확약함.</p></div><p class="stmt">위와 같이 「대전 소상공인·자영업자 재기지원(컨설팅·경영개선) 사업」에 참여하기 위해 사업 참여 및 중복지원 금지 확약서를 제출합니다.</p><div class="sign">{{today}}<br>(업체명) {{business_name}} &nbsp;&nbsp; (대표자) {{owner_name}} &nbsp; {{{sign_applicant}}}</div><p class="foot">(재)대전일자리경제진흥원장 귀하</p></body></html>$html$ where template_key='pledge_no_overlap';

-- 붙임8 하자보증 이행각서
update public.document_templates set name='하자보증 이행각서', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:12.5px;line-height:1.6}.top{text-align:center;font-size:12px;margin:0}h1{text-align:center;font-size:18px;font-weight:800;letter-spacing:2px;margin:2px 0 12px}.sec{font-weight:700;margin:14px 0 5px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:4px 0}th,td{border:1px solid #000;padding:6px 8px;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%}td{text-align:left;width:28%}.sub{font-weight:400;font-size:10.5px;color:#333}.oath{text-align:center;font-weight:700;letter-spacing:3px;margin:16px 0 8px}.stmt{margin:6px 2px;text-align:justify}.sign{margin-top:18px;text-align:center;line-height:2.3}.foot{margin-top:8px;text-align:center;font-weight:800;font-size:14px}</style></head><body><p class="top">대전 소상공인·자영업자 재기지원(경영개선)</p><h1>하자보증이행각서</h1><p class="sec">1. 지원업체 현황</p><table><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>대표자 연락처</th><td>{{phone}}</td></tr></table><p class="sec">2. 외주(제작)업체</p><table><tr><th>업 체 명</th><td>{{contractor_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{contractor_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{contractor_address}}</td></tr><tr><th>대표자</th><td>{{contractor_rep}}</td><th>연락처</th><td>{{contractor_phone}}</td></tr><tr><th>공사내용</th><td colspan="3">{{contractor_work_type}}</td></tr><tr><th>공사기간</th><td colspan="3">　　월　　일　~　　월　　일</td></tr><tr><th>공사금액<br><span class="sub">(부가세별도)</span></th><td colspan="3">{{contractor_amount}}</td></tr></table><p class="oath">이 행 각 서</p><p class="stmt">외주업체가 시행한 위의 공사(또는 제품)에 대한 하자보수를 이행함에 있어 최소 1년 이상의 기간 동안 하자가 발생하는 즉시 실액 변상 또는 재시공할 것을 확약합니다.</p><p class="stmt">※ 각 공사(또는 제품)의 보증기간이 1년 이상인 경우 시공업체의 방침에 따름</p><div class="sign">{{today}}<br>신청업체(대표자) {{owner_name}} &nbsp; {{{sign_applicant}}} &nbsp;&nbsp;&nbsp;&nbsp; 외주업체 대표 {{contractor_rep}} &nbsp; {{{sign_contractor}}}</div><p class="foot">대전일자리경제진흥원장 귀하</p></body></html>$html$ where template_key='pledge_warranty';

-- 붙임9 옥외광고물 표시 신고(허가) 비대상 확인서
update public.document_templates set name='옥외광고물 표시 신고(허가) 비대상 확인서', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:12px;line-height:1.55}.top{text-align:center;font-size:12px;margin:0}h1{text-align:center;font-size:17px;font-weight:800;margin:2px 0 12px}.sec{font-weight:700;margin:12px 0 4px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:4px 0}th,td{border:1px solid #000;padding:6px 8px;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%}td{text-align:left;width:28%}.sub{font-weight:400;font-size:10px;color:#333}.stmt{margin:12px 2px;text-align:justify}.sign{margin-top:14px;text-align:center;line-height:2.2}.foot{margin-top:8px;text-align:center;font-weight:800;font-size:14px}</style></head><body><p class="top">대전 소상공인·자영업자 재기지원사업 경영개선지원</p><h1>옥외광고물 표시 신고(허가) 비대상 확인서</h1><p class="sec">1. 지원업체 현황</p><table><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>대표자 연락처</th><td>{{phone}}</td></tr></table><p class="sec">2. 외주(제작)업체</p><table><tr><th>업 체 명</th><td>{{contractor_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{contractor_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{contractor_address}}</td></tr><tr><th>대표자</th><td>{{contractor_rep}}</td><th>연락처</th><td>{{contractor_phone}}</td></tr><tr><th>옥외광고물 종류</th><td colspan="3">□ 간판 &nbsp;&nbsp; □ LED전광판 &nbsp;&nbsp; □ 기타(　　　　　　　　　)</td></tr><tr><th>비대상근거</th><td colspan="3">□ 신고(허가) 대상의 사이즈 및 광고물이 아닐 경우<br>□ 간판 내부의 LED만 교체했을 경우<br>□ 기타(하단 근거 필수기재)<br>(　　　　　　　　　　　　　　　　　　　　　　　　　　　　)</td></tr></table><p class="sub" style="margin:5px 2px">※ 옥외광고물 제작 업체의 옥외광고업 등록증 사본 1부 별도 첨부</p><p class="stmt">위 사업자의 설치 옥외광고물은 「옥외광고물 등 관리법」 제3조 제1항 및 동법 시행령 제7조 제1항(제9조 제1항)에 따라 신고(허가) 대상이 아님을 확인하며, 무허가 옥외광고물(간판, 전기류 등) 설치로 인한 문제 발생 시 조치할 것을 확약합니다.</p><p class="stmt">※ 전기를 이용하는 광고물(네온류, 전광류 등 포함)은 신고(허가)대상 또한 대전광역시 옥외광고물 등의 관리와 옥외광고산업 진흥에 관한 조례를 준수함을 확약합니다.</p><div class="sign">{{today}}<br>신청업체(대표자) {{owner_name}} &nbsp; {{{sign_applicant}}} &nbsp;&nbsp;&nbsp;&nbsp; 외주업체 대표 {{contractor_rep}} &nbsp; {{{sign_contractor}}}</div><p class="foot">대전일자리경제진흥원장 귀하</p></body></html>$html$ where template_key='outdoor_ad_exempt';

-- 붙임10 영상정보처리기기 운영·관리 방침
update public.document_templates set name='영상정보처리기기 운영·관리 방침', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:12px;line-height:1.55}.top{text-align:center;font-size:12px;margin:0}h1{text-align:center;font-size:17px;font-weight:800;margin:2px 0 12px}.sec{font-weight:700;margin:12px 0 4px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:4px 0}th,td{border:1px solid #000;padding:6px 8px;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%}td{text-align:left;width:28%}.sub{font-weight:400;font-size:10px;color:#333}.stmt{margin:12px 2px;text-align:justify}.sign{margin-top:14px;text-align:center;line-height:2.2}.foot{margin-top:8px;text-align:center;font-weight:800;font-size:14px}</style></head><body><p class="top">대전 소상공인·자영업자 재기지원사업 경영개선지원</p><h1>영상정보처리기기 운영·관리 방침</h1><p class="sec">1. 지원업체 현황</p><table><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr></table><p class="sec">2. 영상정보처리기기 운영·관리 방침</p><table><tr><th>설치목적</th><td colspan="3">□ 시설안전 및 화재 예방 &nbsp;&nbsp;&nbsp;&nbsp; □ 고객 안전 및 범죄 예방</td></tr><tr><th>설치장소</th><td></td><th>설치대수</th><td></td></tr><tr><th>촬영범위</th><td></td><th>촬영시간</th><td></td></tr><tr><th>관리책임자<br><span class="sub">*위탁 시 수탁업체 담당자</span></th><td></td><th>연락처</th><td></td></tr></table><p class="sub" style="margin:5px 2px">※ CCTV 안내판 필수 설치 및 사진 제출 (기재내용 : 설치 목적·장소·범위, 촬영시간, 책임자 성명·연락처)</p><p class="stmt">위 사업자는 「개인정보 보호법」 제25조에 따라 영상정보처리기기를 설치·운영하고 있으며, 개인영상정보의 무단 유출 및 공개를 금지(동법 제18조), 개인영상정보에 관하여 열람 또는 존재 확인·삭제를 요구한 경우 필요한 조치를 하겠습니다.(동법 제35조 및 제36조) 또한 기록된 영상정보를 안전하게 관리(동법 제25조 및 제29조), 개인정보 처리 운영방침 수립 및 공개(동법 제30조)를 확약합니다.</p><div class="sign">{{today}}<br>신청업체(대표자) {{owner_name}} &nbsp; {{{sign_applicant}}}</div><p class="foot">대전일자리경제진흥원장 귀하</p></body></html>$html$ where template_key='cctv_policy';

-- 붙임11 경영개선지원 변경 승인신청서
update public.document_templates set name='경영개선지원 변경 승인신청서', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:12px;line-height:1.55}.top{text-align:center;font-size:12px;margin:0}h1{text-align:center;font-size:17px;font-weight:800;margin:2px 0 12px}.sec{font-weight:700;margin:12px 0 4px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:4px 0}th,td{border:1px solid #000;padding:6px 8px;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%}td{text-align:left;width:28%}.sub{font-weight:400;font-size:10px;color:#333}.stmt{margin:12px 2px;text-align:justify}.sign{margin-top:14px;text-align:center;line-height:2.2}.foot{margin-top:8px;text-align:center;font-weight:800;font-size:14px}</style></head><body><p class="top">대전 소상공인·자영업자 재기지원사업</p><h1>경영개선지원 변경 승인신청서</h1><p class="sec">1. 지원업체 현황</p><table><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr></table><p class="sec">2. 변경 승인내용</p><table><tr><th>단위사업</th><td colspan="3">□위생관리 □안전관리 □홍보(광고) □환경개선 □POS경비 □위생방역</td></tr><tr><th>시공(제작)내용</th><td colspan="3">{{contractor_work_type}}</td></tr><tr><th>시공(제작)금액<br><span class="sub">(부가세 제외)</span></th><td>{{contractor_amount}}</td><th>지원금<br><span class="sub">(소요금액 100%)</span></th><td></td></tr><tr><th>변경내용</th><td colspan="3">□ 시공업체 변경 &nbsp; □ 시공금액 변경 &nbsp; □ 시공내용 변경 &nbsp; □ 기타사유(　　　)</td></tr><tr><th>변경(전)</th><td></td><th>변경(후)</th><td></td></tr><tr><th>완료예정 일자</th><td colspan="3">　　년　　월　　일</td></tr></table><p class="stmt">위 본인은 대전일자리경제진흥원에서 추진하는 대전 소상공인·자영업자 재기지원사업의 경영개선지원사업에 선정되었으나, 상기 이유로 인하여 경영개선지원을 변경하기에 신청서를 제출합니다.</p><div class="sign">{{today}}<br>신청업체(대표자) {{owner_name}} &nbsp; {{{sign_applicant}}}</div><p class="foot">대전일자리경제진흥원장 귀하</p></body></html>$html$ where template_key='change_request';

-- 붙임12 경영개선지원 포기 신청서
update public.document_templates set name='경영개선지원 포기 신청서', html_content=$html$<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>@page{size:A4;margin:16mm 15mm}body{color:#000;font-size:12px;line-height:1.55}.top{text-align:center;font-size:12px;margin:0}h1{text-align:center;font-size:17px;font-weight:800;margin:2px 0 12px}.sec{font-weight:700;margin:12px 0 4px}table{border-collapse:collapse;width:100%;table-layout:fixed;margin:4px 0}th,td{border:1px solid #000;padding:6px 8px;vertical-align:middle}th{background:#f2f2f2;font-weight:700;text-align:center;width:22%}td{text-align:left;width:28%}.sub{font-weight:400;font-size:10px;color:#333}.stmt{margin:12px 2px;text-align:justify}.sign{margin-top:14px;text-align:center;line-height:2.2}.foot{margin-top:8px;text-align:center;font-weight:800;font-size:14px}</style></head><body><p class="top">대전 소상공인·자영업자 재기지원사업</p><h1>경영개선지원 포기 신청서</h1><p class="sec">1. 지원업체 현황</p><table><tr><th>상 호 명</th><td>{{business_name}}</td><th>사업자등록번호<br><span class="sub">(법인등록번호)</span></th><td>{{business_reg_no}}</td></tr><tr><th>사업장 주소</th><td colspan="3">{{address}}</td></tr><tr><th>대표자</th><td>{{owner_name}}</td><th>연락처</th><td>{{phone}}</td></tr></table><p class="sec">2. 포기내용</p><table><tr><th>단위사업</th><td colspan="3">□위생관리 □안전관리 □홍보(광고) □환경개선 □POS경비</td></tr><tr><th>시공(제작)내용</th><td colspan="3">{{contractor_work_type}}</td></tr><tr><th>포기사유</th><td colspan="3" style="height:60px;vertical-align:top"></td></tr></table><p class="stmt">위 본인은 대전일자리경제진흥원에서 추진하는 대전 소상공인·자영업자 재기지원(컨설팅·경영개선) 사업에 선정되었으나, 상기 이유로 인하여 경영개선지원을 포기하기에 신청서를 제출합니다.</p><div class="sign">{{today}}<br>신청업체(대표자) {{owner_name}} &nbsp; {{{sign_applicant}}}</div><p class="foot">대전일자리경제진흥원장 귀하</p></body></html>$html$ where template_key='withdrawal_request';
